function began() {
  var host = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(host)) host = '';
  source.setVariable(JSON.stringify({
    'sytj_type': '', 'sytj_title': '', "频道": "男频", "bd_id": 2, "tone": "tone_id=0",
    "server_id": 0, "server": host, "hosts": host ? [host] : [], "api_key": "", "type": "小说模式", "module": 3,
    "showPara": true, "showChap": true, "showAuthor": true, "showBook": true, "showGod": true, "tone_cn": ""
  }, null, '\t'));
  java.toast('已初始化源变量！');
}

