var sourceConfigReady = false;
try {
  var sourceConfig = JSON.parse(source.getVariable() || '{}');
  sourceConfigReady = !!sourceConfig && typeof sourceConfig === 'object' && !Array.isArray(sourceConfig);
} catch (e) {}
if (!sourceConfigReady) {
  java.toast('检测到异常源变量，正在重新初始化');
  began();
}

let arr = [],
    个人中心 = 1;

