    j.name = action.name;
    j.type = action.type;
    j.chars = action.chars;
    j.viewName = action.viewName;
    j.default = action.default;
  }
  arr.push(j);
}

function zwf(len, cols, num) {
  if (len % cols !== 0) {
    let count = cols - len % cols;
    for (let i = 0; i < count; i++) {
      push(_zwf, '', num, 1, {
        "type": "button",
        "action": "java.toast('这是占位符')"
      });
    }
  }
}

function infoValue(name, fallback) {
  try {
    if (typeof infoMap !== 'undefined' && infoMap) {
      var value = infoMap[name];
      if ((value === undefined || value === null || value === '') && infoMap.get) value = infoMap.get(name);
      if (value !== undefined && value !== null && value !== '') return String(value);
    }
  } catch (e) {}
  return fallback;
}

function schemaValue(schema, name) {
  var match = String(schema || '').match(new RegExp('[?&]' + name + '=([^&]+)', 'i'));
  if (!match) return '';
  try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
}

function categoryParams(atom, genreOverride) {
  atom = atom || {};
  var schema = String(atom.category_landpage_url || '');
  return {
    categoryId: schemaValue(schema, 'categoryId') || String(atom.category_id || ''),
    subCategoryIds: schemaValue(schema, 'subCategoryIds'),
    genreType: genreOverride || schemaValue(schema, 'genreType'),
    gender: schemaValue(schema, 'gender')
  };
}

function categoryUrl(params) {
  if (!params.categoryId) return '';
  var path = '/api/landing?category_id=' + encodeURIComponent(params.categoryId);
  if (params.subCategoryIds) path += '&sub_category_ids=' + encodeURIComponent(params.subCategoryIds);
  if (params.genreType) path += '&genre_type=' + encodeURIComponent(params.genreType);
  if (params.gender) path += '&gender=' + encodeURIComponent(params.gender);
  path += '&offset={{(page-1)*10}}';
  return API.call(this, path);
}

function loadCategoryFile(fileIndex, genreOverride) {
  try {
    var root = requestJSON.call(this, '/sy/' + fileIndex + '.json');
    var tabData = root.data && root.data.category_tab_data || {};
    var cells = tabData.cell_data || [];
    cells.forEach(function(cell) {
      var atoms = cell.atom_data || [];
      if (!atoms.length) return;
      var first = atoms[0].category_data || {};
      push(cell.cell_name || first.name || '分类', categoryUrl.call(this, categoryParams(first, genreOverride)), 1, 1, {});
      for (var i = 1; i < atoms.length; i++) {
        var atom = atoms[i].category_data || {};
        var url = categoryUrl.call(this, categoryParams(atom, genreOverride));
        if (url && atom.name) push(atom.name, url, 0.25, 1, {});
      }
      zwf(Math.max(0, atoms.length - 1), numx, 0.25);
    }, this);
