// ===== 工具函数 =====
// ===== v0.76 配置读快照（跨引擎调用很贵：见文件头注释） =====
// 宿主里 source.getVariable()/cache.get 都是跨引擎调用（真机 2.6-5ms/次），而配置读
// 出现在每条规则的开头。同一规则链（一本书的一个阶段）里连读十几次配置没有任何意义，
// 这里加一层同引擎内存快照：
//   - 快照存活 1200ms，SET 立即改写快照 ⇒ 同一规则链内「写后读」一致；
//   - 过期后重新跨引擎读一次 ⇒ 设置面板改完立刻生效（面板写的是同一个缓存键）；
//   - 快照按 bookSourceUrl 隔离 ⇒ 多源共用 jsLib 作用域时不会串味。
// 只加速读：写仍然 cache.put + source.setVariable 双写，重启后配置还在。
var _pyfqCfgMemo = { key: '', at: 0, data: null };
var _pyfqCfgTtlMs = 1200;

function _pyfqCfgKeyOf() {
  var src = (this && this.source) ? this.source : null;
  try { return String((src && src.bookSourceUrl) || ''); } catch (e) { return ''; }
}

function _pyfqCfgLoad(force) {
  var src = (this && this.source) ? this.source : null;
  var cch = (this && this.cache) ? this.cache : null;
  var key = _pyfqCfgKeyOf.call(this);
  var now = Date.now();
  if (!force && _pyfqCfgMemo.data && _pyfqCfgMemo.key === key && (now - _pyfqCfgMemo.at) < _pyfqCfgTtlMs) {
    return _pyfqCfgMemo.data;
  }
  var d = {};
  try { if (src) d = JSON.parse(src.getVariable() || '{}') || {}; } catch (e0) { d = {}; }
  if (cch) {
    try {
      var c = JSON.parse(cch.get('pyfqSourceConfig:' + encodeURIComponent(key)) || '{}');
      if (c && typeof c === 'object') { for (var ck in c) { if (Object.prototype.hasOwnProperty.call(c, ck)) d[ck] = c[ck]; } }
    } catch (e1) {}
  }
  if (!d || typeof d !== 'object') d = {};
  _pyfqCfgMemo = { key: key, at: now, data: d };
  return d;
}

function GET(k) {
  var d = _pyfqCfgLoad.call(this, false);
  return Object.prototype.hasOwnProperty.call(d, k) ? d[k] : '';
}

function SET(k, v) {
  var src = (this && this.source) ? this.source : null;
  var cch = (this && this.cache) ? this.cache : null;
  var key = _pyfqCfgKeyOf.call(this);
  var d = _pyfqCfgLoad.call(this, true) || {};
  d[k] = v;
  var raw = JSON.stringify(d);
  // 先落快照再落盘：写盘失败（部分宿主没有 setVariable）时同一次求值内也不再读到旧值。
  _pyfqCfgMemo = { key: key, at: Date.now(), data: d };
  if (cch) { try { cch.put('pyfqSourceConfig:' + encodeURIComponent(key), raw); } catch (e2) {} }
  if (src) { try { src.setVariable(raw); } catch (e3) { try { src.putVariable('pyfqSourceConfig', raw); } catch (e4) {} } }
  return v;
}

function getHostList() {
  var src = (this && this.source) ? this.source : null;
  var d = _pyfqCfgLoad.call(this, false);
  var list = d['hosts'];
  if (!Array.isArray(list)) list = String(list || '').split(/\r?\n/);
  list = list.map(function(x) { return String(x || '').trim().replace(/\/+$/, ''); })
    .filter(function(x, i, arr) { return /^https?:\/\//i.test(x) && arr.indexOf(x) === i; });
  // 源地址始终入池（与 loginUrl 版本一致）：用户换过线的场景里 bookSourceUrl 往往是
  // 早已失效的导入地址，只有「当前线路」才是可用的那一个（见 _pyfqHostOrder）。
  var sourceHost = '';
  try { sourceHost = String((src && src.bookSourceUrl) || '').trim().replace(/\/+$/, ''); } catch (e2) {}
  if (/^https?:\/\//i.test(sourceHost) && list.indexOf(sourceHost) < 0) list.push(sourceHost);
  return list;
}

// _pyfqHostOrder 探测/请求候选顺序：当前线路排第一，其余按原顺序去重。
// 死地址排首位时旧实现每次请求都要先等一个连接超时（真机 10s 量级）。
function _pyfqHostOrder() {
  var list = getHostList.call(this);
  var current = '';
  try { current = String(GET.call(this, 'server') || '').trim().replace(/\/+$/, ''); } catch (e) {}
  var order = [];
  if (/^https?:\/\//i.test(current)) order.push(current);
  for (var i = 0; i < list.length; i++) { if (list[i] !== current) order.push(list[i]); }
  return { order: order, current: current };
}

function buildApiUrl(path, host) {
  var src = (this && this.source) ? this.source : null;
  var base = String(host || GET.call(this, 'server') || (src && src.bookSourceUrl) || '').trim().replace(/\/+$/, '');
  var url = base + (String(path || '').startsWith('/') ? path : '/' + path);
  var key = GET.call(this, 'api_key');
  if (!key) {
    try { key = ((src && src.getLoginInfoMap ? src.getLoginInfoMap() : null) || {})['API密钥'] || ''; } catch (e) {}
  }
  if (key && !/[?&]api_key=/.test(url)) url += (url.indexOf('?') >= 0 ? '&' : '?') + 'api_key=' + encodeURIComponent(key);
  return url;
}

function autoSetHost(force) {
  var java = this.java;
  var state = _pyfqHostOrder.call(this);
  var order = state.order;
  if (!order.length) return '';
  var lastCheck = Number(GET.call(this, 'server_check_time') || 0);
  if (!force && state.current && Date.now() - lastCheck < 60000) return state.current;
  var start = Number(GET.call(this, 'server_id') || 0) % order.length;
  for (var i = 0; i < order.length; i++) {
    var id = (start + i) % order.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl.call(this, '/api/health', order[id])));
      if (root && root.code === 0) {
        SET.call(this, 'server', order[id]);
        SET.call(this, 'server_id', id);
        SET.call(this, 'server_check_time', Date.now());
        return order[id];
      }
    } catch (e) {}
    // 避免请求过快阻塞 JS 引擎：连续请求间暂停 200ms
    if (i % 4 === 3 && i < order.length - 1) {
      try { java.sleep(200); } catch (se) {}
    }
  }
  // 全灭也要打时间戳：否则下一次读配置立刻重扫一遍死地址（每次一个连接超时的阻塞），
  // 目录阶段会退化成「每章一次卡顿」。60 秒内只扫一次；设置面板的「重新探测」走 force=1。
  SET.call(this, 'server_check_time', Date.now());
  return state.current || order[0];
}

function API(path) {
  return buildApiUrl.call(this, path, autoSetHost.call(this, false));
}

function requestJSON(path) {
  var java = this.java;
  var state = _pyfqHostOrder.call(this);
  var order = state.order;
  var current = state.current;
  if (!order.length) return { code: -1, msg: '未配置服务器地址' };
  var start = Math.max(0, order.indexOf(current));
  var lastError = '';
  for (var i = 0; i < order.length; i++) {
    var id = (start + i) % order.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl.call(this, path, order[id])));
      SET.call(this, 'server', order[id]);
      SET.call(this, 'server_id', id);
      SET.call(this, 'server_check_time', Date.now());
      if (!root || root.code !== 0) {if (root && (root.code === -401 || root.code === -429)) {try { java.toast('⛔ ' + (root.msg || '请求受限') + '\n可在书源登录面板查看/申领密钥，额度见 /key/status'); } catch (eToast) {}}throw new Error((root && root.msg) || '接口返回异常');}
      return root;
    } catch (e) { lastError = String(e); }
    // 避免请求过快阻塞：每4个请求间暂停 200ms
    if ((i + 1) % 4 === 0 && i < order.length - 1) {
      try { java.sleep(200); } catch (se) {}
    }
  }
  throw new Error(lastError || '所有服务器均不可用');
}

function queryValue(url, name) {
  var match = String(url || '').match(new RegExp('[?&]' + name + '=([^&]+)', 'i'));
  if (!match) return '';
  try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
}

function moduleFromUrl(url, fallback) {
  var value = Number(queryValue(url, 'ys_module') || fallback || 3);
  return [2, 3, 8, 11, 13, 19].indexOf(value) >= 0 ? value : 3;
}

function moduleFromCurrentResult(fallback) {
  var java = this.java;
  function value(rule) {
    try { return String(java.getString(rule) || ''); } catch (e) { return ''; }
  }
  var ysModule = Number(value('ys_module||$.ys_module||$.book_info.ys_module||$.history.ys_module'));
  if ([2, 3, 8, 11, 13, 19].indexOf(ysModule) >= 0) return ysModule;
  var comicType = value('comic_book_type||$.comic_book_type||$.book_info.comic_book_type||$.history.comic_book_type');
  var genreType = value('genre_type||$.genre_type||$.video_detail.genre_type||$.book_info.genre_type||$.history.genre_type');
