function getComments(content, bookId, itemId) {
  var java = this.java, cache = this.cache;
  try {
    var separator = '\n';
    if (/<p>/.test(content)) { content = content.replace('<p>','').replace(/<\/p>/g, '').replace('\n', ''); separator = '<p>'; } else { content = content.replace(/\r/g, '').replace(/\n$/, ''); }
    var comcont = content.split(separator);
    comcont.forEach(function(item, idx) { comcont[idx] = item.replace(/[\r\n]/g, '').trim(); });
    // 登录态计数：带 sessionid 时上游返回同一用户全部评论（气泡与段评面板同步）
    var sid = '';
    try { sid = String((this.cookie && this.cookie.getKey) ? this.cookie.getKey('fanqienovel.com', 'sessionid') : ''); } catch (eS1) {}
    try { if (!sid && (this.source && this.source.getLoginInfoMap)) { var sim = this.source.getLoginInfoMap() || {}; sid = String(sim['手动登录Token'] || sim.get && sim.get('手动登录Token') || ''); } } catch (eS2) {}
    sid = String(sid || '').trim();
    var root = requestJSON.call(this, '/api/comment_count?item_id=' + encodeURIComponent(itemId) + (sid ? '&sessionid=' + encodeURIComponent(sid) : ''));
    var comments = root.data && root.data.data ? root.data.data : {};
    var commentList = [];
    Object.keys(comments).forEach(function(paragraphId) {
      var item = comments[paragraphId] || {};
      commentList.push({ paragraphId: paragraphId, textCount: Number(item.count || item) || 0 });
    });
    commentList.forEach(function(x) {
      if (x.textCount > 0 && comcont[x.paragraphId]) {
        comcont[x.paragraphId] += '<img src="' + createSvg.call({source: this.source, java: java, cache: cache}, x.textCount, bookId, itemId, x.paragraphId) + '">';
      }
    }.bind(this));
    // 任意段落写段评：count=0 的段落挂迷你写段评气泡
    // （写入段评后刷新正文缓存，comment_count 返回该段 count>0，自动替换为正式段评气泡）
    if (switchEnabled.call(this, 'writePara')) {
      var hasCount = {};
      commentList.forEach(function(x) { hasCount[x.paragraphId] = true; });
      comcont.forEach(function(seg, idx) {
        if (!hasCount[idx] && seg) {
          comcont[idx] += '<img src="' + createMiniBubble.call({source: this.source, java: java, cache: cache}, bookId, itemId, idx) + '" style="width:14px;height:14px;display:inline;">';
        }
      });
    }
    return comcont.join('\n');
  } catch (e) { java.log(e); return content; }
}

