function readerActionRows(value, names, maxDepth) {
  var rows = [];
  function walk(node, depth) {
    if (!node || depth < 0 || typeof node !== 'object') return;
    if (Array.isArray(node)) {
      node.forEach(function(item) { walk(item, depth - 1); });
      return;
    }
    Object.keys(node).forEach(function(key) {
      var child = node[key];
      if (names.indexOf(key) >= 0 && Array.isArray(child)) {
        child.forEach(function(item) { if (item) rows.push(item); });
      } else if (child && typeof child === 'object') {
        walk(child, depth - 1);
      }
    });
  }
  walk(value, Number(maxDepth || 6));
  return rows;
}

function readerActionHasBody(value) {
  var queue = [value];
  var wrappers = ['comment','post','topic','common','content','chapter_data','chapter_info','author_say'];
  for (var depth = 0; depth < 4 && queue.length; depth++) {
    var next = [];
    for (var i = 0; i < queue.length; i++) {
      var item = queue[i];
      if (typeof item === 'string' && item.replace(/\s+/g, '') !== '') return true;
      if (!item || typeof item !== 'object') continue;
      var textKeys = ['text','content','title','description','abstract','post_content','message','author_content','pure_content','topic_content','topic_title'];
      for (var j = 0; j < textKeys.length; j++) {
        var text = item[textKeys[j]];
        if (typeof text === 'string' && text.replace(/\s+/g, '') !== '') return true;
        if (text && typeof text === 'object') next.push(text);
      }
      var mediaKeys = ['image_data_list','image_list','images','image_url','video_url'];
      for (var m = 0; m < mediaKeys.length; m++) {
        var media = item[mediaKeys[m]];
        if ((Array.isArray(media) && media.length) || (typeof media === 'string' && media !== '')) return true;
      }
      wrappers.forEach(function(key) { if (item[key] && typeof item[key] === 'object') next.push(item[key]); });
    }
    queue = next;
  }
  return false;
}

function readerActionAvailability(bookId, itemId, enabled) {
  var result = {chapter: 0, author: 0, related: 0};
  // v0.77：三个横幅计数改走服务端聚合接口（内联并发 + 10 分钟缓存），
  // 原实现每章串行发 4 个请求（forum_id → end_comments 拉 30 条全文 → author_say → recommendations），
  // 是正文刷新「每章 7 连请求」里最重的一段；现在合并为 1 个请求。
  if (!enabled.chapter && !enabled.author && !enabled.related) return result;
  try {
    var actionsUrl = '/api/reader_actions?book_id=' + encodeURIComponent(bookId)
      + '&item_id=' + encodeURIComponent(itemId)
      + '&chapter=' + (enabled.chapter ? 1 : 0)
      + '&author=' + (enabled.author ? 1 : 0)
      + '&related=' + (enabled.related ? 1 : 0);
    var actionsRoot = requestJSON.call(this, actionsUrl);
