function defaultSourceConfig() {
  return {
    'sytjs': typeof sytjs === 'undefined' ? [] : sytjs,
    'sytj_type': '',
    'sytj_title': '',
    "频道": "男频",
    "bd_id": 2,
    "tone": "tone_id=0",
    "server_id": 0,
