    "tone_cn": "",
    "videoQuality": "high",
    "richToc": false,
    "audioSubtitle": false,
    "richIntro": true,
    "commentDefaultsVersion": 4,
    "isRandomBubble": false
  };
}

function normalizeSourceConfig(data) {
  var state = data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  var defaults = defaultSourceConfig();
  for (var key in defaults) {
    if (Object.prototype.hasOwnProperty.call(defaults, key) && !Object.prototype.hasOwnProperty.call(state, key)) {
      state[key] = defaults[key];
    }
  }
  var sourceHost = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(sourceHost)) sourceHost = '';
  var configuredHosts = state.hosts;
  if (!Array.isArray(configuredHosts)) configuredHosts = String(configuredHosts || '').split(/\r?\n/);
  configuredHosts = configuredHosts.map(function(host) { return String(host || '').trim().replace(/\/+$/, ''); })
    .filter(function(host, index, values) { return /^https?:\/\//i.test(host) && values.indexOf(host) === index; });
  if (sourceHost && configuredHosts.indexOf(sourceHost) < 0) configuredHosts.push(sourceHost);
  var activeHost = String(state.server || '').trim().replace(/\/+$/, '');
  if (/^https?:\/\//i.test(activeHost) && configuredHosts.indexOf(activeHost) < 0) configuredHosts.push(activeHost);
  if (!/^https?:\/\//i.test(activeHost)) activeHost = configuredHosts[0] || '';
  state.hosts = configuredHosts;
  state.server = activeHost;
  state.server_id = Math.max(0, configuredHosts.indexOf(activeHost));
  return state;
}

function syncSourceSwitches(state) {
  ['showPara','showChap','showAuthor','showBook','showGod','richToc','audioSubtitle','richIntro'].forEach(function(name) {
    try { java.put(name, state[name] === true); } catch (e) {}
  });
