// 保持沐凡原源 GET/SET 写法，避免登录面板函数影响发现页规则。
function GET(k) {
  var d = {};
  try { d = JSON.parse(source.getVariable() || '{}'); } catch (e) { d = {}; }
  return Object.prototype.hasOwnProperty.call(d, k) ? d[k] : '';
