// 检测服务器
function checkNet() {
  var hosts = getHostList();
  if (!hosts.length) { java.longToast('\n\n没有可用的服务器地址\n请先在「服务器配置」里填写'); return; }
  java.longToast('\n\n♻️正在检测 ' + hosts.length + ' 条线路\n请稍等~');
  var current = Number(GET('server_id') || 0);
  var rows = [], bestId = -1, bestMs = -1, okCount = 0;
  for (var i = 0; i < hosts.length; i++) {
    var url = hosts[i], ms = -1, begin = Date.now();
    try {
      var root = JSON.parse(java.ajax(buildApiUrl.call(this, '/api/health', url)));
      if (root && root.code === 0) ms = Date.now() - begin;
    } catch (e) {}
    // 避免请求过快阻塞 JS 引擎：每 4 个请求间暂停 200ms
    if (i % 4 === 3 && i < hosts.length - 1) {
      try { java.sleep(200); } catch (se) {}
    }
    var tag, detail;
    if (ms < 0) { tag = '💔 不可用'; detail = '无响应'; }
    else if (ms < 1000) { tag = '💖 优良'; detail = '❤️延迟低，推荐使用此接口❤️'; }
    else if (ms < 2000) { tag = '💛 一般'; detail = '♦️延迟一般，勉强可使用♦️'; }
    else if (ms < 5000) { tag = '♠ 堪忧'; detail = '♠延迟过高，不建议使用♠'; }
    else { tag = '♣️ 过高'; detail = '请切换其他接口或网络环境'; }
    if (ms >= 0) {
      okCount++;
      if (bestMs < 0 || ms < bestMs) { bestMs = ms; bestId = i; }
    }
    var card = (i === current ? '▶️ 当前线路\n' : '') + '[' + (i + 1) + '] ' + tag
      + '\n┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n【' + url + '】\n┋┋\n'
      + (ms >= 0 ? '解析时间：' + (ms / 1000) + 's\n' + detail : detail)
      + '\n┋┋\n┗┅━┅━┅━┅━┅┅━┅━┅┛';
    rows.push(card);
  }
  var head = !okCount ? '💔【全部线路不可用】' : bestMs < 1000 ? '💖【网络环境优良】' : bestMs < 2000 ? '💛【网络环境一般】' : '♠【网络环境堪忧】';
  var foot = !okCount ? '请检查服务是否启动或切换网络环境' : bestId === current ? '❤️当前线路延迟最低，推荐保持❤️' : '♦️建议切换到第 ' + (bestId + 1) + ' 条线路♦️';
  java.longToast('\n' + head + '\n' + rows.join('\n\n') + '\n\n' + foot
    + '\n可用 ' + okCount + '/' + hosts.length + ' 条');
}

