function normalizeHostLines(raw) {
  raw = String(raw === null || raw === undefined ? '' : raw).trim();
  return raw.split(/\r?\n/).map(function(x) { return x.trim().replace(/\/+$/, ''); })
    .filter(function(x, i, arr) { return /^https?:\/\//i.test(x) && arr.indexOf(x) === i; });
}

function saveHosts(raw, silent) {
  var list = normalizeHostLines(raw);
  if (!list.length) {
    if (!silent) java.toast('请按每行一个地址填写服务器');
    return false;
  }
  var d = readSourceConfig();
  d.hosts = list;
  d.server_id = 0;
  d.server = list[0];
  d.server_check_time = 0;
  writeSourceConfig(d);
  try { java.refreshExplore(); } catch (eExplore) {}
  if (!silent) java.toast('已保存 ' + list.length + ' 条服务器线路，发现页已按新线路重载');
