function escapeConfigHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildServerConfigHtml() {
  var cfg = readSourceConfig();
  var hostsValue = getHostList.call(this).join('\n');
  var keyValue = String(cfg.api_key || '');
  cfg.hosts = normalizeHostLines(hostsValue);
  cfg.server = String(cfg.server || cfg.hosts[0] || '');
  cfg.server_id = Number(cfg.server_id || 0);
