function configHtmlUnescape(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function configFieldEdited(body, id) {
  var match = String(body || '').match(new RegExp('id="d_' + id + '"[^>]*>\\s*([^<]*?)\\s*<\\/span>', 'i'));
  return !!(match && String(match[1] || '').trim() === '1');
}

function configPanelValue(body, id, tagName) {
  body = String(body === null || body === undefined ? '' : body);
  var encoded = '';
  var spanMatch = body.match(new RegExp('id="v_' + id + '"[^>]*>\\s*([^<]*?)\\s*<\\/span>', 'i'));
  if (spanMatch) encoded = configHtmlUnescape(String(spanMatch[1] || '').trim());
  var value = '';
  if (encoded) {
    try { value = decodeURIComponent(encoded); } catch (e0) { value = encoded; }
  }
  value = String(value || '').trim();
  if (configFieldEdited(body, id)) return value;
  var fallback = '';
  if (tagName === 'textarea') {
    var textMatch = body.match(new RegExp('<textarea[^>]*id="in_' + id + '"[^>]*>([\\s\\S]*?)<\\/textarea>', 'i'));
    if (textMatch) fallback = configHtmlUnescape(textMatch[1]);
  } else {
    var inputMatch = body.match(new RegExp('<input[^>]*id="in_' + id + '"[^>]*\\svalue="([^"]*)"', 'i'));
    if (inputMatch) fallback = configHtmlUnescape(inputMatch[1]);
  }
  return value || String(fallback || '').trim();
}

function applyServerConfigValues(rawHosts, key) {
  var list = normalizeHostLines(rawHosts);
  if (!list.length) return 0;
  var d = readSourceConfig();
  d.hosts = list;
  d.server_id = 0;
  d.server = list[0];
  d.server_check_time = 0;
  d.api_key = String(key === null || key === undefined ? d.api_key || '' : key).trim();
  writeSourceConfig(d);
  return list.length;
}

function applyServerConfigUrl(url) {
  var match = String(url || '').match(/[#&]cfg=([^&]+)/);
  if (!match) return 0;
  try {
    var d = JSON.parse(decodeURIComponent(match[1]));
    return applyServerConfigValues((d.hosts || []).join('\n'), d.api_key);
  } catch (e) {
    return 0;
  }
}

function applyServerConfigBody(body) {
  body = String(body === null || body === undefined ? '' : body);
  if (!body) return 0;
  var rawHosts = configPanelValue(body, 'hosts', 'textarea');
  var key = configPanelValue(body, 'api_key', 'input');
  return applyServerConfigValues(rawHosts, key);
}

function openServerConfigPanel() {
  try {
    var html = buildServerConfigHtml.call(this);
    var list = getHostList.call(this);
    var panelUrl = 'http://127.0.0.1/__legado_server_config__';
    if (list.length && /^https?:\/\//i.test(list[0])) {
      panelUrl = String(list[0]).replace(/\/+$/, '') + '/__legado_server_config__';
    }
    var response = java.startBrowserAwait(panelUrl, '服务器配置', false, html);
    var count = 0;
    try { count = applyServerConfigUrl.call(this, response.url()); } catch (eUrl) { count = 0; }
    if (!count) {
      var body = '';
      try { body = String(response.body() || ''); } catch (eBody) { body = ''; }
      count = applyServerConfigBody.call(this, body);
    }
    if (count > 0) java.toast('已保存 ' + count + ' 条服务器线路');
    else java.toast('未解析到服务器地址，请重新打开配置');
  } catch (e) {
    java.log('服务器配置失败：' + e);
    java.toast('服务器配置失败，请查看日志');
  }
}

